// Enrutamiento dinámico de fuentes de scraping
const input = $input.first().json;

// 1. Si el Webhook proporciona una URL específica, procesar solo esa URL
if (input.targetUrl && typeof input.targetUrl === 'string' && input.targetUrl.startsWith('http')) {
  const target = input.targetUrl.trim();
  const isPdf = target.toLowerCase().endsWith('.pdf') || target.toLowerCase().includes('/pdf/');
  return [{
    json: {
      url: target,
      source_name: input.sourceName || (isPdf ? 'Documento PDF Bancario' : 'Portal Personalizado'),
      vertical: input.vertical || 'real_estate',
      is_pdf: isPdf,
      is_custom_trigger: true
    }
  }];
}

// 2. Si es ejecución de Cron o sin URL específica, procesar el catálogo bancario completo
const defaultCatalog = [
  {
    url: 'https://www.banconal.com.pa/index.php/bienes-y-remates/bienes-adquiridos',
    source_name: 'Banco Nacional',
    vertical: 'real_estate',
    is_pdf: false
  },
  {
    url: 'https://www.cajadeahorros.com.pa/propiedades-reposeidas/propiedades-reposeidas/',
    source_name: 'Caja de Ahorros',
    vertical: 'real_estate',
    is_pdf: false
  },
  {
    url: 'https://www.cajadeahorros.com.pa/propiedades-reposeidas/autos-reposeidos/',
    source_name: 'Caja de Ahorros Autos',
    vertical: 'vehicles',
    is_pdf: false
  },
  {
    url: 'https://www.baccredomatic.com/es-pa/personas/bienes-adquiridos',
    source_name: 'BAC Panama',
    vertical: 'real_estate',
    is_pdf: false
  }
];

return defaultCatalog.map(item => ({ json: item }));

