// Normalizar schema HOIE y calcular hash determinista inmutable para InsForge
const parsed = $json.output || $json;
const list = Array.isArray(parsed.assets) ? parsed.assets : [];
const validItems = [];

for (const item of list) {
  const price = Number(item.price_amount);
  if (!item.title || isNaN(price) || price <= 0) continue;

  const rawSource = $('Enrutador Dinámico de Fuentes').item.json.source_name || 'Desconocido';
  const sourceId = rawSource.toLowerCase().replace(/[^a-z0-9]+/g, '-');
  const listingUrl = (item.source_listing_url && item.source_listing_url.startsWith('http')) 
    ? item.source_listing_url.trim() 
    : $('Enrutador Dinámico de Fuentes').item.json.url;

  // Hash determinista inmutable (basado en fuente, url y título, SIN precio)
  const hashSeed = sourceId + '::' + listingUrl + '::' + String(item.title).trim();
  let hash = 0;
  for (let i = 0; i < hashSeed.length; i++) {
    hash = ((hash << 5) - hash) + hashSeed.charCodeAt(i);
    hash |= 0;
  }
  const assetId = 'ast_' + Math.abs(hash).toString(16);

  const loc = item.location || {};
  const province = loc.province || 'Panamá';
  const corregimiento = loc.corregimiento || 'Bella Vista';
  const district = loc.district || (province === 'Panamá' ? 'Panamá' : corregimiento);

  validItems.push({
    asset_id: assetId,
    vertical: item.vertical === 'vehicles' ? 'vehicles' : 'real_estate',
    title: String(item.title).trim(),
    price_amount: price,
    currency: 'USD',
    location: {
      province: province,
      district: district,
      corregimiento: corregimiento
    },
    raw_data: {
      specs: item.specs || {},
      description: item.description || '',
      extracted_by: 'n8n_groq_pipeline',
      extracted_at: new Date().toISOString()
    },
    source_id: sourceId,
    source_listing_url: listingUrl,
    status: 'active',
    updated_at: new Date().toISOString()
  });
}

return validItems.map(obj => ({ json: obj }));
